import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"三江","description":"","frontmatter":{"title":"三江","date":"2026-11-17T00:00:00.000Z","seq":3,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/三江.md","filePath":"blogs/声律启蒙·上卷/三江.md"}'),r={name:"blogs/声律启蒙·上卷/三江.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="三江" tabindex="-1">三江 <a class="header-anchor" href="#三江" aria-label="Permalink to &quot;三江&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">楼对阁，户对窗，巨海对长江。蓉裳对蕙帐，玉斝对银釭。青布幔，碧油幢，宝剑对金缸。忠心安社稷，利口覆家邦。世祖中兴延马武，桀王失道杀龙逄。秋雨潇潇，漫烂黄花都满径；春风袅袅，扶疏绿竹正盈窗。</p><p class="poem-stanza">旌对旆，盖对幢，故国对他邦。千山对万水，九泽对三江。山岌岌，水淙淙，鼓振对钟撞。清风生酒舍，皓月照书窗。阵上倒戈辛纣战，道旁系剑子婴降。夏日池塘，出没浴波鸥对对；春风帘幕，往来营垒燕双双。</p><p class="poem-stanza">铢对两，只对双，华岳对湘江。朝车对禁鼓，宿火对寒缸。青琐闼，碧纱窗，汉社对周邦。笙箫鸣细细，钟鼓响摐摐。主簿栖鸾名有览，治中展骥姓惟庞。苏武牧羊，雪屡餐于北海；庄周活鲋，水必决于西江。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
